requests.testScript:
test('status is 201', () => {
  expect(response.status).toBe(201);
});
test('collection has a generated id', () => {
  expect(response.json().id).toMatch(/^col-/);
});
test('collection name is stored', () => {
  expect(response.json().name).toBe('CLI Regression Suite');
});
test('capture id for later requests', () => {
  environment.set('createdCollectionId', response.json().id);
});

test('status is 200', () => {
  expect(response.status).toBe(200);
});
test('returns the created collection', () => {
  expect(response.json().id).toBe(environment.get('createdCollectionId'));
  expect(response.json().name).toBe('CLI Regression Suite');
});
test('new collection starts empty', () => {
  expect(response.json().requests).toHaveLength(0);
  expect(response.json().folders).toHaveLength(0);
});

test('status is 200', () => {
  expect(response.status).toBe(200);
});
test('description is updated', () => {
  expect(response.json().description).toBe("Updated by Requesto's self-test suite");
});

test('status is 201', () => {
  expect(response.status).toBe(201);
});
test('copy gets a new id', () => {
  expect(response.json().id).toMatch(/^col-/);
  expect(response.json().id).not.toBe(environment.get('createdCollectionId'));
});
test('copy is named after the original', () => {
  expect(response.json().name).toBe('CLI Regression Suite Copy');
});
test('capture id for cleanup', () => {
  environment.set('duplicateCollectionId', response.json().id);
});

